import math
from functools import reduce

def lcm(a, b):
    """Calculates the least common multiple of two numbers."""
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def lcm_of_range(start, length):
    """Calculates the LCM of the sequence start, start+1, ..., start+length-1."""
    if length <= 0:
        return 1
    numbers = range(start, start + length)
    return reduce(lcm, numbers)

# Parameters
N_values = [3, 4, 5]
K_max = 15

results = {}

for n in N_values:
    print(f"--- Results for n = {n} ---")
    sequence_data = {}
    violation_count = 0
    violations = []

    # Calculate x_k for k=1 up to K_max
    x_values = {}
    for k in range(1, K_max + 1):
        x_k = lcm_of_range(k, n)
        x_values[k] = x_k

    # Check condition x_{k+1} <= x_k for k=1 up to K_max-1
    for k in range(1, K_max):
        x_k = x_values[k]
        x_k_plus_1 = x_values[k+1]

        if x_k_plus_1 <= x_k:
            violation_count += 1
            violations.append((k, x_k, x_k_plus_1))

    results[n] = {
        "x_values": x_values,
        "violations": violations,
        "count": violation_count
    }

    # Print structured output for easier recording
    print(f"x_values for n={n} (k=1 to {K_max}): {x_values}")
    if violations:
        print(f"Violations (x_{{k+1}} <= x_k) found for n={n}: {violations}")
    else:
        print(f"No violations found for n={n}.")

# Prepare data for note writing
